uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// --- ASSETS ---
uniform sampler2D iChannel0; 

// --- STANDARD CONTROLS ---
uniform float u_speed;
uniform float u_camera_dist; 
uniform float u_fov;
uniform float u_glow_intensity;

// --- VISUAL CONTROLS ---
uniform float u_turbulence_strength;
uniform float u_cloud_height; 
uniform float u_color_shift;
uniform float u_density_factor;
uniform float u_saturation;

out vec4 fragColor;

// --- LUMINA MATH LIB ---
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    // rd: Ray direction using provided FOV logic
    vec3 rd = normalize(vec3(uv, -1.0 / max(0.1, u_fov))); 

    float t = iTime * ((u_speed <= 0.0) ? 0.2 : u_speed);

    // Accumulation
    vec4 col = vec4(0.0);

    // Start distance: offset slightly to ensure we are looking AT the volume
    float d = 1.0 + u_camera_dist; 

    for(int i = 0; i < 80; i++) {
        vec3 p = d * rd;

        // Turbulence Loop: Swizzling and Sine waves for "Mixing Paint"
        float scale = 1.5;
        vec3 p_orig = p;
        for(int j = 0; j < 5; j++) {
            p.xy *= rot(t * 0.05 + float(j) * 0.5);
            // Swizzling p.yzx for 3D turbulence
            p += u_turbulence_strength * sin(p.yzx * scale - t) / scale;
            scale *= 1.7;
        }

        // Separation logic: Ridge/Stringy calculation
        // abs(p.y) creates horizontal "sheets" or "strings"
        float strands = u_cloud_height - abs(p.y);

        // Step size: Smaller steps inside the paint for high-fidelity filaments
        float stepSize = 0.02 + max(strands, -strands * 0.2) * 0.5;
        d += stepSize;

        // Color logic
        float hue = fract(u_color_shift + p_orig.x * 0.1 + t * 0.05);
        vec3 pigment = hsv2rgb(vec3(hue, max(0.5, u_saturation), 1.0));

        // Heat Map: Black -> Red -> Orange -> White (Getty Style)
        vec3 fireCol = mix(vec3(0.1, 0.0, 0.0), pigment, smoothstep(-0.2, 0.2, strands));

        // Glow: Exponential density logic from Lumina
        float glow = exp(strands / (0.15 / max(0.1, u_density_factor)));

        // Accumulate
        col.rgb += fireCol * glow * (u_glow_intensity * 0.015);

        if (col.a > 0.99) break;
    }

    // Tone Mapping: Tanh-like compression to handle brightness
    vec3 finalCol = col.rgb * col.rgb;
    finalCol = 1.0 - exp(-finalCol * 0.8); // Filmic compression

    // Final Polish
    finalCol = pow(finalCol, vec3(1.2, 1.1, 1.0));

    fragColor = vec4(finalCol, 1.0);
}
